// 4-input LUT: cfg holds the 16 truth-table bits
assign out = cfg[in];
// cfg = 16'h8000 -> AND of 4 inputs
// cfg = 16'h6996 -> XOR of 4 inputs

files.text:
module lut4(input [3:0] in, input [15:0] cfg, output out);
  assign out = cfg[in];
endmodule

module lut4_tb;
  reg [3:0] in; reg [15:0] cfg; wire out; integer i, errors;
  lut4 dut(.in(in), .cfg(cfg), .out(out));
  initial begin
    errors = 0;
    cfg = 16'h8000;
    for (i = 0; i < 16; i = i + 1) begin
      in = i; #1;
      if (out !== (&in)) errors = errors + 1;
    end
    cfg = 16'h6996;
    for (i = 0; i < 16; i = i + 1) begin
      in = i; #1;
      if (out !== (^in)) errors = errors + 1;
    end
    $display("AND and XOR LUT checks done, errors=%0d", errors);
    if (errors == 0) $display("PASS"); else $display("FAIL");
    $finish;
  end
endmodule

module clkdiv(input clk, input rst, output reg slow);
  reg [1:0] c;
  always @(posedge clk) begin
    if (rst) begin
      c <= 2'd0;
      slow <= 1'b0;
    end else begin
      c <= c + 2'd1;
      if (c == 2'd1) begin
        slow <= ~slow;
        c <= 2'd0;
      end
    end
  end
endmodule

module clkdiv_tb;
  reg clk, rst; wire slow; integer i, errors; reg [7:0] seen; reg [7:0] expect_bits;
  clkdiv dut(.clk(clk), .rst(rst), .slow(slow));
  initial clk = 0;
  always #5 clk = ~clk;
  initial begin
    errors = 0; rst = 1; seen = 8'd0; expect_bits = 8'b01100110;
    @(posedge clk); #1; rst = 0;
    for (i = 7; i >= 0; i = i - 1) begin
      @(posedge clk); #1;
      seen[i] = slow;
    end
    $display("slow over 8 cycles = %b", seen);
    if (seen !== expect_bits) errors = errors + 1;
    if (errors == 0) $display("PASS"); else $display("FAIL");
    $finish;
  end
endmodule
